"""Duration text parser."""
import re

_UNITS = {"h": 3600, "m": 60, "s": 1}
_PART = re.compile(r"(\d+)([hms])")


def parse_duration(text):
    """Return the number of seconds in a duration such as "1h30m" or "45s"."""
    if text.isdigit():
        return int(text)
    total = 0
    for number, unit in _PART.findall(text):
        total += int(number) * _UNITS[unit]
    return total

import unittest

from duration import parse_duration


class DurationUnits(unittest.TestCase):
    def test_hours_and_minutes(self):
        self.assertEqual(parse_duration("1h30m"), 5400)

    def test_minutes_and_seconds(self):
        self.assertEqual(parse_duration("2m5s"), 125)

    def test_seconds_unit(self):
        self.assertEqual(parse_duration("45s"), 45)

    def test_bare_number_is_seconds(self):
        self.assertEqual(parse_duration("90"), 90)

    def test_number_after_hours_is_minutes(self):
        self.assertEqual(parse_duration("1h30"), 5400)

    def test_uppercase_unit(self):
        self.assertEqual(parse_duration("1H"), 3600)

    def test_surrounding_spaces(self):
        self.assertEqual(parse_duration(" 3m "), 180)

    def test_zero(self):
        self.assertEqual(parse_duration("0s"), 0)

import unittest

from duration import parse_duration


class DurationRejects(unittest.TestCase):
    def test_rejects_empty(self):
        with self.assertRaises(ValueError):
            parse_duration("")

    def test_rejects_unit_without_number(self):
        with self.assertRaises(ValueError):
            parse_duration("h")

    def test_rejects_malformed_hour_suffix(self):
        with self.assertRaises(ValueError):
            parse_duration("1h30x")

    def test_rejects_units_out_of_order(self):
        with self.assertRaises(ValueError):
            parse_duration("30m1h")

    def test_rejects_repeated_unit(self):
        with self.assertRaises(ValueError):
            parse_duration("1m1m")

    def test_rejects_sign(self):
        with self.assertRaises(ValueError):
            parse_duration("-5s")

    def test_rejects_non_string(self):
        with self.assertRaises(TypeError):
            parse_duration(90)

